}","import React, { useState, useEffect, useCallback } from "react";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import { Card } from "@servicenow/react-components/Card";
import { Badge } from "@servicenow/react-components/Badge";
import "./styles.css";

const TABLE = "x_828868_tool_le_0_loan_rec";
const COLUMNS = "equipment,member,checkout_date,due_date,status";

interface Counts {
 pending: number;
 active: number;
 overdue: number;
}

async function fetchCount(query: string): Promise<number> {
 const res = await fetch(
 `/api/now/table/${TABLE}?sysparm_query=${query}&sysparm_limit=1&sysparm_fields=sys_id&sysparm_display_value=all`,
 { headers: { Accept: "application/json", "X-UserToken": (window as any).g_ck } }
 );
 return parseInt(res.headers.get("X-Total-Count") || "0", 10);
}

function SummaryCards({ counts }: { counts: Counts }) {
 return (
 <div className="summary-row">
 <Card className="summary-card">
 <div className="summary-card__value summary-card__value--warning">
 {counts.pending}
 </div>
 <div className="summary-card__label">Pending Approvals</div>
 </Card>
 <Card className="summary-card">
 <div className="summary-card__value summary-card__value--info">
 {counts.active}
 </div>
 <div className="summary-card__label">Active Loans</div>
 </Card>
 <Card className="summary-card">
 <div className="summary-card__value summary-card__value--critical">
 {counts.overdue}
 </div>
 <div className="summary-card__label">Overdue Items</div>
 </Card>
 </div>
 );
}

function navigateToRecord(sysId: string) {
 const path = `/x_828868_tool_le_0_loan_rec.do?sys_id=${sysId}`;
 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath: path,
 title: "Loan Record",
 });
 }
 window.location.href = path;
}

function handleRowClick(e: any) {
 const sysId = e.detail?.payload?.sys_id;
 if (sysId) navigateToRecord(sysId);
}

/* Cast to pass the `query` prop which the underlying web component supports
 but the React wrapper's TypeScript types don't expose */
const FilteredRecordList = NowRecordListConnected as any;

export default function App() {
 const [counts, setCounts] = useState<Counts>({ pending: 0, active: 0, overdue: 0 });

 useEffect(() => {
 Promise.all([
 fetchCount("status=pending_approval"),
 fetchCount("status=active"),
 fetchCount("status=overdue"),
 ]).then(([pending, active, overdue]) =>
 setCounts({ pending, active, overdue })
 );
 }, []);

 return (
 <div className="staff-dashboard">
 <div className="staff-dashboard__title">Staff Dashboard</div>
 <SummaryCards counts={counts} />

 <div className="section">
 <div className="section__header">
 <div className="section__title">Pending Approvals</div>
 <Badge value={counts.pending} appearance="filled" />
 </div>
 <FilteredRecordList
 table={TABLE}
 columns={COLUMNS}
 query="status=pending_approval"
 listTitle="Pending Approvals"
 hideHeader={true}
 onRowClicked={handleRowClick}
 />
 </div>

 <div className="section">
 <div className="section__header">
 <div className="section__title">Active Loans</div>
 <Badge value={counts.active} appearance="filled" />
 </div>
 <FilteredRecordList
 table={TABLE}
 columns={COLUMNS}
 query="status=active"
 listTitle="Active Loans"
 hideHeader={true}
 onRowClicked={handleRowClick}
 />
 </div>

 <div className="section">
 <div className="section__header">
 <div className="section__title">Overdue Items</div>
 <Badge value={counts.overdue} appearance="filled" color="critical" />
 </div>
 <FilteredRecordList
 table={TABLE}
 columns={COLUMNS}
 query="status=overdue"
 listTitle="Overdue Items"
 hideHeader={true}
 onRowClicked={handleRowClick}
 />
 </div>
 </div>
 );
}
